package copdem

import (
	_ "embed"
	"errors"
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"
	"sync"
)

// tiles.txt is generated by scripts/gen-copdem-tiles.py from the bucket's
// tileList.txt: the existing tiles of the region, one "N55E012" line each.

//go:embed tiles.txt
var tilesText string

// The region: south-west corners of every tile a profile can reach. A
// profile is at most 80 km long and the fill runs only for one with a
// sample DHM covers, so every sample is within 80 km of DHM's raster
// extent (54.57–57.78° N, 8.0–15.6° E): 53.85–58.50° N and 6.6–16.9° E.
// scripts/gen-copdem-tiles.py uses the same numbers.
const (
	regionSouth, regionNorth = 53, 58
	regionWest, regionEast   = 6, 16
	regionCols               = regionEast - regionWest + 1
	regionTiles              = (regionNorth - regionSouth + 1) * regionCols
)

// Tile is one 1°×1° GLO-30 tile, by the latitude and longitude of its
// south-west corner.
type Tile struct{ Lat, Lon int }

// TileAt is the tile holding (lat, lon): the floor of each. ok is false
// for a position that is not a finite latitude and longitude.
func TileAt(lat, lon float64) (Tile, bool) {
	if !(lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180) {
		return Tile{}, false
	}
	return Tile{int(math.Floor(lat)), int(math.Floor(lon))}, true
}

// InRegion reports whether t is in the region the tile list covers.
func (t Tile) InRegion() bool {
	return t.Lat >= regionSouth && t.Lat <= regionNorth && t.Lon >= regionWest && t.Lon <= regionEast
}

// Listed reports whether t exists in the bucket. A tile in the region
// that is not listed is sea; outside the region nothing is listed.
func (t Tile) Listed() bool { return tileList().has(t) }

func (t Tile) String() string { return fmt.Sprintf("N%02dE%03d", t.Lat, t.Lon) }

// name is the bucket's name for t, in the region's hemispheres.
func (t Tile) name() string {
	return fmt.Sprintf("Copernicus_DSM_COG_10_N%02d_00_E%03d_00_DEM", t.Lat, t.Lon)
}

// Path is the URL path of t's GeoTIFF in the bucket.
func (t Tile) Path() string { return "/" + t.name() + "/" + t.name() + ".tif" }

// tilePathRe is the allow-list of request paths: a GLO-30 1″ DEM tile
// in the region, folder and file named alike. Nothing else in the bucket
// (tileList.txt, the AUXFILES, other products) is ever requested.
var tilePathRe = regexp.MustCompile(`^/Copernicus_DSM_COG_10_N(5[3-8])_00_E(0(?:0[6-9]|1[0-6]))_00_DEM/Copernicus_DSM_COG_10_N5[3-8]_00_E0(?:0[6-9]|1[0-6])_00_DEM\.tif$`)

// errPath is the one refusal of a path off the allow-list.
var errPath = errors.New("copdem: path not allowed")

// checkPath accepts p only if it is the Path of a listed tile.
func checkPath(p string) error {
	m := tilePathRe.FindStringSubmatch(p)
	if m == nil {
		return errPath
	}
	// The folder names the tile; the file must be the same tile (RE2 has
	// no back-references, so equality with Path checks it).
	lat, _ := strconv.Atoi(m[1])
	lon, _ := strconv.Atoi(m[2])
	if t := (Tile{lat, lon}); !t.Listed() || t.Path() != p {
		return errPath
	}
	return nil
}

// tileSet is the region's tiles, one flag each.
type tileSet [regionTiles]bool

func (s *tileSet) has(t Tile) bool {
	return t.InRegion() && s[(t.Lat-regionSouth)*regionCols+t.Lon-regionWest]
}

var tileLineRe = regexp.MustCompile(`^N([0-9]{2})E([0-9]{3})$`)

var errTiles = errors.New("malformed tile list")

// parseTiles reads "N55E012" lines; "#" lines and blank lines are skipped.
// A tile outside the region is an error, so the list and the region
// cannot drift apart.
func parseTiles(text string) (*tileSet, error) {
	var s tileSet
	n := 0
	for _, line := range strings.Split(text, "\n") {
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		m := tileLineRe.FindStringSubmatch(line)
		if m == nil {
			return nil, errTiles
		}
		lat, _ := strconv.Atoi(m[1])
		lon, _ := strconv.Atoi(m[2])
		t := Tile{lat, lon}
		if !t.InRegion() {
			return nil, errTiles
		}
		s[(lat-regionSouth)*regionCols+lon-regionWest] = true
		n++
	}
	if n == 0 {
		return nil, errTiles
	}
	return &s, nil
}

var tileList = sync.OnceValue(func() *tileSet {
	s, err := parseTiles(tilesText)
	if err != nil {
		panic("copdem: embedded tiles.txt: " + err.Error())
	}
	return s
})
